import{_ as n,C as s,o as i,c as r,E as a,a2 as o}from"./chunks/framework.Cm6XCzck.js";const c="/joinwell52/assets/figures/2026-08-28-response-loss-comparison.en.svg",f=JSON.parse('{"title":"CodeFlowMu Engineering Record (I): After Response Loss, Why Retry Must Start with a Persistent Idempotency Boundary","description":"","frontmatter":{"title":"CodeFlowMu Engineering Record (I): After Response Loss, Why Retry Must Start with a Persistent Idempotency Boundary","date":"2026-08-28","updated":"2026-08-31","column":"open-source-engineering","category":"daily","article_type":"engineering-case-study","edition":"research-center","research_question":"When a side effect has already happened but the response is lost, how can an Agent Runtime use persistent submission identity to distinguish safe retry, result reuse, and conflict rejection?","summary":"A response-loss experiment exposed an engineering boundary in CodeFlowMu task creation: in the historical version, retrying the same business intent could create a second TASK. V2.1.2 moved a stable client_submission_id, request_digest, a three-stage creation receipt, and recovery rules into the Runtime; independent QA then verified that response loss and eight-way concurrency converge on one authoritative task_id.","sources":"/en/research/evidence/2026-08-28-response-loss-idempotency","project_relevance":"substantive-relationship","item_id":"RBE-20260828-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-28-response-loss-idempotency-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-28-response-loss-idempotency.md","filePath":"en/engineering/2026-08-28-response-loss-idempotency.md","lastUpdated":1788148073000}'),d={name:"en/engineering/2026-08-28-response-loss-idempotency.md"};function l(h,e,u,p,m,y){const t=s("ArticleCover");return i(),r("div",null,[a(t,{image:"/assets/covers/daily-2026-08-28-response-loss-idempotency-cover.png",kicker:"CodeFlowMu Engineering Record · 01",title:"After Response Loss, Why Retry Must Start with a Persistent Idempotency Boundary",summary:"Not receiving a success response does not mean the action never happened. Reliable retry is not about executing again; it is about recovering the result of the first execution.",version:"RBE-20260828-01",status:"Engineering Case · Revised 2026-08-31",languageHref:"/zh/engineering/2026-08-28-response-loss-idempotency",languageLabel:"中文"}),e[0]||(e[0]=o('<h1 id="codeflowmu-engineering-record-i-after-response-loss-why-retry-must-start-with-a-persistent-idempotency-boundary" tabindex="-1">CodeFlowMu Engineering Record (I): After Response Loss, Why Retry Must Start with a Persistent Idempotency Boundary <a class="header-anchor" href="#codeflowmu-engineering-record-i-after-response-loss-why-retry-must-start-with-a-persistent-idempotency-boundary" aria-label="Permalink to &quot;CodeFlowMu Engineering Record (I): After Response Loss, Why Retry Must Start with a Persistent Idempotency Boundary&quot;">​</a></h1><p>For an Agent Runtime, “can I retry after a tool error?” is not merely a networking question.</p><p>The dangerous window is this: <strong>the side effect has already happened, but the caller never received the success response.</strong></p><p>A task has already been persisted, yet the response disappears on the way back. After recovery, the caller only knows that it did not receive a result, so it submits the same business intent again. If the Runtime cannot prove what the first call already did, the second “retry” can become a second real creation.</p><h2 id="what-codeflowmu-is-and-why-this-deserves-its-own-engineering-boundary" tabindex="-1">What CodeFlowMu is, and why this deserves its own engineering boundary <a class="header-anchor" href="#what-codeflowmu-is-and-why-this-deserves-its-own-engineering-boundary" aria-label="Permalink to &quot;What CodeFlowMu is, and why this deserves its own engineering boundary&quot;">​</a></h2><p>CodeFlowMu is a <strong>local-first multi-agent collaboration and digital-employee runtime</strong>. It does more than hand prompts to a model: PM, DEV, QA, OPS, EVAL, and other role agents execute real work in controlled workspaces while the Runtime manages task objects, execution context, tool calls, events, recovery, and evidence.</p><p>Unlike a one-shot chat, this kind of system runs for longer periods and must survive process exits, Host interruptions, network faults, schedule recovery, and repeated wake-ups. Once a tool call can create a real side effect, the Runtime cannot use “did the caller receive success?” as its only evidence that the action happened.</p><p>Idempotency is therefore not a small API optimization in CodeFlowMu. It is a recovery boundary for digital employees: <strong>the system must distinguish first creation, recovery of the same business submission, and a genuinely new business intent.</strong></p><p>The full experiment, version boundary, and public evidence are available in the <a href="/joinwell52/en/research/evidence/2026-08-28-response-loss-idempotency">RBE-20260828-01 evidence pack</a>.</p><h2 id="external-research-origin-an-exception-does-not-prove-that-the-side-effect-never-happened" tabindex="-1">External research origin: an exception does not prove that the side effect never happened <a class="header-anchor" href="#external-research-origin-an-exception-does-not-prove-that-the-side-effect-never-happened" aria-label="Permalink to &quot;External research origin: an exception does not prove that the side effect never happened&quot;">​</a></h2><p>The external starting point for this research chain was <a href="https://github.com/run-llama/llama_index/pull/22841" target="_blank" rel="noreferrer">LlamaIndex PR #22841</a>, <code>fix(core): avoid retrying failed function tools</code>.</p><p>Its concrete issue was that the invocation layer could execute a FunctionTool with one argument form and, after an exception, try another form by executing the tool again. The first exception did not necessarily occur before the side effect. If the first call had already written, sent, or created something, the second “try another calling convention” attempt could duplicate the real action.</p><p>LlamaIndex fixed its own problem by deciding the argument form before the real invocation, based on the function signature, rather than using a potentially side-effecting execution to probe the interface.</p><p>The value of that external case for CodeFlowMu was not a patch to copy. It supplied a failure model worth testing in our own Runtime:</p><blockquote><p>When the caller sees an exception, can the system prove that the side effect has not already happened? If not, what fact makes a retry safe?</p></blockquote><p>The external work raises the question. Whether CodeFlowMu had an analogous engineering gap had to be answered by first-party implementation evidence and experiments.</p><h2 id="first-party-reproduction-one-response-loss-window-two-different-write-behaviors" tabindex="-1">First-party reproduction: one response-loss window, two different write behaviors <a class="header-anchor" href="#first-party-reproduction-one-response-loss-window-two-different-write-behaviors" aria-label="Permalink to &quot;First-party reproduction: one response-loss window, two different write behaviors&quot;">​</a></h2><p>The original experiment was fixed to CodeFlowMu V2.0.4 commit <code>2ba1ad9b</code>. It was not a production-incident statistic. It deliberately created the response-loss window in which the action completed but the caller lost the success result.</p><table tabindex="0"><thead><tr><th>Tested layer</th><th>Historical observation</th><th>Engineering meaning</th></tr></thead><tbody><tr><td>Upper-layer in-memory dedup</td><td>The first action occurred, but its success result never entered the reusable cache; recovery entered the execution path again</td><td>Process-local caching cannot resolve an unknown result across recovery</td></tr><tr><td><code>write_report</code></td><td>Retrying the same task, content, and submission identity returned <code>deduplicated=true</code>; report count remained 1</td><td>The tested report path already had persistent result reuse</td></tr><tr><td><code>write_task</code></td><td>Retrying the same business creation intent entered real creation again, received a new task identity, and TASK count became 2</td><td>Task creation did not bind a stable submission identity to the result of the first creation</td></tr></tbody></table><p><img src="'+c+'" alt="Historical response-loss experiment: one report, two tasks"></p><p><em>Figure 1. Historical V2.0.4 comparison, not V2.1.2 behavior. Counts apply only to the tested paths and are not production incidence. Source: <a href="/joinwell52/en/research/evidence/2026-08-28-response-loss-idempotency">RBE-20260828-01 evidence pack</a>.</em></p><p>This comparison matters because it rules out an overbroad conclusion. The result was not “all CodeFlowMu write tools lack idempotency.”</p><p><code>write_report</code> was the counterexample. It showed that permitting a retry at the upper layer does not necessarily create a second side effect if the underlying interface already has durable identity and result-reuse semantics.</p><p>The actual gap was concentrated in task creation. At that point, <code>write_report</code> already exposed <code>client_submission_id</code>, while <code>write_task</code> did not yet have an equivalent formal persistent-idempotency contract. The caller thinking “this is still the same submission” is not the same thing as the Runtime having durably recorded and recognized that business identity.</p><h2 id="engineering-judgment-reliable-retry-is-not-fuzzy-deduplication-it-is-recovery-of-the-first-result" tabindex="-1">Engineering judgment: reliable retry is not fuzzy deduplication; it is recovery of the first result <a class="header-anchor" href="#engineering-judgment-reliable-retry-is-not-fuzzy-deduplication-it-is-recovery-of-the-first-result" aria-label="Permalink to &quot;Engineering judgment: reliable retry is not fuzzy deduplication; it is recovery of the first result&quot;">​</a></h2><p>After observing two TASK objects, the easiest proposed fix would be: look for an existing task with the same title before creating a new one.</p><p>That is not reliable idempotency.</p><p>The same title, summary, sender, or time window can legitimately describe two different business intents. Conversely, one business submission can be retried with a different trace, connection, process, or retry count. Fuzzy content matching can both miss duplicates and suppress legitimate new work.</p><p>CodeFlowMu V2.1.2 therefore framed the problem differently:</p><p><strong>How do we give one creation intent a stable, persistent, recoverable identity that can also detect conflicts?</strong></p><p>That framing is the key engineering change: retry stops being merely a caller strategy and becomes part of the task-creation interface contract.</p><h2 id="v2-1-2-make-one-business-submission-a-persistent-fact" tabindex="-1">V2.1.2: make one business submission a persistent fact <a class="header-anchor" href="#v2-1-2-make-one-business-submission-a-persistent-fact" aria-label="Permalink to &quot;V2.1.2: make one business submission a persistent fact&quot;">​</a></h2><p>V2.1.2 establishes the relation:</p><p><code>client_submission_id → request_digest → task_id / task_path → creation_result</code></p><p><code>client_submission_id</code> identifies one business creation intent, not one HTTP, MCP, or process invocation. A caller that needs recovery across response loss or process restart must reuse the same stable ID.</p><p>If it generates a new ID on retry, the Runtime treats that as a new business intent. That is not an idempotency failure; the caller supplied a new identity.</p><p>A stable ID alone is still insufficient. If the same ID first asks DEV to fix login and is later reused to ask OPS to deploy an environment, the Runtime must not silently reuse the first result. V2.1.2 therefore persists a normalized <code>request_digest</code> as well.</p><p>The implementation uses a <code>write-task-v1</code> digest scheme. It constructs deterministic JSON from semantic fields including sender, recipient, subject, body, priority, thread_key, parent, references, depends_on, and risk_level, then computes SHA-256. Object keys are ordered; strings normalize Unicode NFC and line endings; arrays preserve order. Invocation-time fields such as call time, retry count, or trace ID are not part of the business digest.</p><p>The Runtime also persists <code>digest_schema_version</code>. If the same submission ID arrives with a different digest or digest schema, it returns <code>conflict</code> and produces no new TASK side effect.</p><p>This is a <strong>task-creation interface contract</strong>, not a claim that the entire Runtime is a general-purpose transaction database. Existing <code>write_report</code> deduplication semantics remain unchanged, and the FCoP TASK / REPORT / REVIEW / EVAL protocol did not change as part of this patch.</p><h2 id="why-a-three-stage-creation-receipt-is-still-necessary" tabindex="-1">Why a three-stage creation receipt is still necessary <a class="header-anchor" href="#why-a-three-stage-creation-receipt-is-still-necessary" aria-label="Permalink to &quot;Why a three-stage creation receipt is still necessary&quot;">​</a></h2><p>If the system only writes “this submission succeeded” after the TASK file has been created, a narrower crash window remains:</p><ol><li>the TASK is persisted successfully;</li><li>the final receipt has not yet been written;</li><li>the process exits;</li><li>the caller retries with the same submission ID.</li></ol><p>If the Runtime only checks for the final receipt, it can still mistakenly create again.</p><p>V2.1.2 therefore persists the creation result through three stages:</p><p><code>reserved → task_created → committed</code></p><table tabindex="0"><thead><tr><th>State</th><th>Durable fact already available</th><th>Recovery rule</th></tr></thead><tbody><tr><td><code>reserved</code></td><td>submission ID, digest schema, digest, preallocated task identity and path</td><td>If the TASK does not exist, continue with the same identity; if it exists and matches, adopt that task rather than allocate a new number</td></tr><tr><td><code>task_created</code></td><td>TASK creation and file digest confirmed</td><td>If matching, finish committing the receipt; if the file is unexpectedly missing, return a typed conflict rather than pretend creation never happened</td></tr><tr><td><code>committed</code></td><td>Complete machine-readable creation result</td><td>Same ID + same digest reuses the first result without executing creation again</td></tr></tbody></table><p>Submission-level mutual exclusion and task-number protection handle concurrent reservation. Atomic persistence and recovery rules for intermediate states handle crash recovery. If the target path exists but the identity or content does not match, the system may not hide uncertainty by overwriting it or creating a second task.</p><p>For reservations that remain in an intermediate state for an unusually long time, the Runtime exposes read-only diagnostics: current state, whether the target TASK exists, whether digests match, and whether the reservation has stalled. Diagnostics report facts only; a timeout does not automatically delete the reservation or make a business decision to recreate the task.</p><h2 id="created-reused-conflict-make-retry-results-machine-readable" tabindex="-1"><code>created</code>, <code>reused</code>, <code>conflict</code>: make retry results machine-readable <a class="header-anchor" href="#created-reused-conflict-make-retry-results-machine-readable" aria-label="Permalink to &quot;`created`, `reused`, `conflict`: make retry results machine-readable&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>disposition</code></th><th><code>action_taken</code></th><th>Meaning</th></tr></thead><tbody><tr><td><code>created</code></td><td><code>true</code></td><td>This call completed the first creation</td></tr><tr><td><code>reused</code></td><td><code>false</code></td><td>The creation result already exists; return the authoritative identity produced by the first call</td></tr><tr><td><code>conflict</code></td><td><code>false</code></td><td>The submission identity conflicts with an existing digest or recovery fact; no new TASK is created</td></tr></tbody></table><p><code>action_taken=false</code> is not necessarily failure. In the <code>reused</code> case it is precisely the evidence that the Runtime did not perform a second creation while still recovering the original success result.</p><p>“Success” here means that the task-object creation result was recovered. It does not mean the task has been executed, QA has passed, or the business outcome has been delivered. Technical idempotency does not replace higher-level governance state.</p><p>Compatibility is also stated narrowly. Legacy callers that omit <code>client_submission_id</code> can continue to use the earlier creation path, but that path is not claimed to have the stronger cross-response-loss, cross-process idempotency guarantee.</p><h2 id="independent-qa-count-authoritative-objects-not-merely-exceptions" tabindex="-1">Independent QA: count authoritative objects, not merely exceptions <a class="header-anchor" href="#independent-qa-count-authoritative-objects-not-merely-exceptions" aria-label="Permalink to &quot;Independent QA: count authoritative objects, not merely exceptions&quot;">​</a></h2><p>After implementation, QA that did not participate in the change independently exercised response-loss and concurrency scenarios. Acceptance focused on real TASK count, whether <code>task_id</code> remained identical, and the returned creation receipt.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Independent QA observation</th></tr></thead><tbody><tr><td>A2: simulate lost response after successful creation, then retry with the same submission identity</td><td>TASK count 1; same <code>task_id</code>; second call <code>reused / action_taken=false</code></td></tr><tr><td>A4: eight concurrent calls with the same submission ID and digest</td><td><code>created=1 / reused=7</code>; one unique <code>task_id</code>; TASK count 1</td></tr></tbody></table><p>Process-restart reuse, same-ID/different-digest conflict, legacy response compatibility, missing intermediate files, and stale-reservation diagnostics also have targeted tests.</p><p>The evidence boundary matters: A2/A4 independently show convergence for two critical failure models in the tested task-creation contract. They do not mean that every tool, Host, or network environment has independently received the same validation.</p><p>For the engineering issue at hand, however, the before/after distinction is concrete:</p><p><strong>In the historical tested version, one creation intent could produce two TASK objects after response loss. In V2.1.2, tested retry, concurrency, and restart paths that reuse a stable submission ID and consistent digest converge on one authoritative task identity.</strong></p><h2 id="from-patch-to-product-version-release-gates-still-matter" tabindex="-1">From patch to product version: release gates still matter <a class="header-anchor" href="#from-patch-to-product-version-release-gates-still-matter" aria-label="Permalink to &quot;From patch to product version: release gates still matter&quot;">​</a></h2><p>CodeFlowMu V2.1.2 was released on August 30, 2026. Its Runtime and Shell source code is maintained in a private repository. Public articles do not link directly to the private CodeFlowMu repository; externally reviewable version facts, sanitized QA results, and scope statements are consolidated in the <a href="/joinwell52/en/research/evidence/2026-08-28-response-loss-idempotency">public evidence pack</a> and the <a href="/joinwell52/en/research/evidence/2026-08-30-codeflowmu-v2.1.2-public-release-summary">V2.1.2 Public Release Summary</a>.</p><p>Final release validation recorded:</p><ul><li>Runtime: <strong>1842 pass / 0 fail / 1 skip</strong>;</li><li>Shell: <strong>1037 pass / 0 fail / 0 skip</strong>;</li><li>same-protocol critical matrices for V2.1.1 and V2.1.2, ten consecutive rounds each: Runtime <strong>1630/1630</strong>, Shell <strong>550/550</strong>;</li><li>typecheck, Shell build, installer contract, rules, and version consistency passed.</li></ul><p>These are results of the release test suites. They must not be added together or described as an “idempotency reliability rate.”</p><p>The release covers the CodeFlowMu Runtime and Shell maintained in a private repository. It is not Open Dev Team Edition and it does not imply that real LAN/Gateway environments, browser profiles, or user production projects were covered by the same fixtures. The one Windows symlink-permission skip, pre-existing dependency-audit warnings, and the Python targeted-fixture warning remain part of the evidence notes.</p><h2 id="what-the-engineering-change-actually-changed" tabindex="-1">What the engineering change actually changed <a class="header-anchor" href="#what-the-engineering-change-actually-changed" aria-label="Permalink to &quot;What the engineering change actually changed&quot;">​</a></h2><p>Previously, the caller saw “the request did not return successfully” and had to guess whether to try again.</p><p>With a stable submission identity, the Runtime can now distinguish three different facts:</p><ul><li>this is the first creation, so execute and return a new result;</li><li>this is recovery of the same business submission, so return the original result;</li><li>this request conflicts with an already-reserved submission identity, so reject new side effects.</li></ul><p>Retry thus becomes a persistent, recoverable, auditable, testable contract instead of a guess made by the caller.</p><p>That difference matters especially for a digital-employee runtime. Digital employees run for long periods, cross process boundaries, are reawakened by schedulers, and can encounter uncertainty at Host, network, and tool layers. If every recovery requires an Agent to guess whether the previous action actually succeeded, the system has not yet crossed from demo behavior into a production runtime.</p><h2 id="a-review-checklist-for-other-agent-runtimes" tabindex="-1">A review checklist for other Agent Runtimes <a class="header-anchor" href="#a-review-checklist-for-other-agent-runtimes" aria-label="Permalink to &quot;A review checklist for other Agent Runtimes&quot;">​</a></h2><p>For every side-effecting tool, ask at least:</p><ol><li>If the side effect is persisted and the response is lost, can a process restart recover the first result?</li><li>Does same stable ID + same request mean result reuse or another execution?</li><li>Does same ID + different request produce an explicit conflict with zero new side effects?</li><li>Are “check + reserve + create” protected consistently under concurrency?</li><li>Can intermediate states resume under the original identity rather than escaping uncertainty by creating a new object?</li><li>Are legacy calls kept compatible without falsely advertising the same idempotency level?</li><li>Do already-correct tool paths keep their protection instead of regressing during a unified rewrite?</li></ol><p>A Runtime whose only answer is “if it fails, try again” has not fully defined its side-effect boundary.</p><p>A stronger answer is: <strong>every retryable business intent has a persistent identity that survives response loss, concurrency, and process recovery.</strong></p><h2 id="engineering-conclusion" tabindex="-1">Engineering conclusion <a class="header-anchor" href="#engineering-conclusion" aria-label="Permalink to &quot;Engineering conclusion&quot;">​</a></h2><p>This CodeFlowMu change does not prove that every Agent tool is safe to retry. It demonstrates a narrower and more useful proposition:</p><p><strong>An external failure model can be narrowed through first-party positive and negative experiments into a concrete interface gap, then turned into an executable Runtime contract through persistent submission identity, request digests, creation receipts, a recovery state machine, and independent QA.</strong></p><p>The real question exposed by response loss was never simply “should we call again?”</p><p>It was whether the system had enough durable facts to answer, when the second call arrived:</p><p><strong>What exactly did the first call already do?</strong></p><h2 id="evidence-scope-and-primary-sources" tabindex="-1">Evidence scope and primary sources <a class="header-anchor" href="#evidence-scope-and-primary-sources" aria-label="Permalink to &quot;Evidence scope and primary sources&quot;">​</a></h2><ul><li><a href="/joinwell52/en/research/evidence/2026-08-28-response-loss-idempotency">Historical experiment, V2.1.2 engineering update, and public version evidence</a>: public JSON fixture, Reader, and check validate frozen historical material; the page also maps the sanitized implementation evidence, independent QA, release gate, and residual-risk statements.</li><li><a href="https://github.com/run-llama/llama_index/pull/22841" target="_blank" rel="noreferrer">LlamaIndex PR #22841</a>: external failure model and calling-convention fix context; it is not CodeFlowMu implementation or acceptance evidence.</li><li>CodeFlowMu V2.1.2 implementation, independent QA, and raw release logs remain in the private repository; this public article does not provide inaccessible private-repository links as reader-facing evidence.</li><li>Production incidence, every operating system, real LAN/Gateway deployments, and user production projects are outside this article&#39;s evidence scope.</li></ul>',86))])}const b=n(d,[["render",l]]);export{f as __pageData,b as default};
